    private UnauthenticatedSessionTracker tracker;
    private final List<FakeHttpSession> sessions = new ArrayList<>();
    private final List<TrackingToken> reservedTokens = new ArrayList<>();
    private Boolean trackResult;

    private void givenTracker() {
        this.tracker = new UnauthenticatedSessionTracker();
    }

    private void givenSessions(final int count) {
        for (int i = 0; i < count; i++) {
            this.sessions.add(new FakeHttpSession());
        }
    }

    private void givenTrackedSessions(final int count, final int maxCount) {
        for (int i = 0; i < count; i++) {
            assertTrue("session " + i + " should have been tracked", trackSession(i, maxCount));
        }
    }

    private void givenAuthenticatedSession(final int index) {
        this.sessions.get(index).setAttribute(Attributes.AUTORIZED_USER.getValue(), "kura.admin");
    }

    private void givenReleasedSession(final int index) {
        this.tracker.release(this.sessions.get(index));
    }

    private void givenReservedSlots(final int count, final int maxCount) {
        for (int i = 0; i < count; i++) {
            try {
                this.reservedTokens.add(this.tracker.reserveToken(maxCount));
            } catch (final KuraException e) {
                fail("slot " + i + " should have been reserved");
            }
        }
    }

    private void whenSessionIsTracked(final int index, final int maxCount) {
        this.trackResult = trackSession(index, maxCount);
    }

    private void whenSessionIsTrackedWithoutLimit(final int index) {
        trackSession(index, Integer.MAX_VALUE);
    }

    private void whenSlotIsReserved(final int maxCount) {
        try {
            this.reservedTokens.add(this.tracker.reserveToken(maxCount));
            this.trackResult = true;
        } catch (final KuraException e) {
            this.trackResult = false;
        }
    }

    private void whenSessionIsAttached(final int index) {
        final TrackingToken token = this.reservedTokens.remove(this.reservedTokens.size() - 1);
        token.attach(this.sessions.get(index));
    }

    private void whenSessionIsReleased(final int index) {
        this.tracker.release(this.sessions.get(index));
    }

    private void whenSessionIsInvalidated(final int index) {
        this.sessions.get(index).invalidate();
    }

    private void thenSessionIsAccepted() {
        assertNotNull(this.trackResult);
        assertTrue("the session should have been accepted", this.trackResult);
    }

    private void thenSessionIsRejected() {
        assertNotNull(this.trackResult);
        assertFalse("the session should have been rejected", this.trackResult);
    }

    private void thenTrackedSessionCountIs(final int expected) {
        assertEquals(expected, this.tracker.getTrackedSessionCount());
    }

    private void thenSessionIsMarkedAsUnauthenticated(final int index) {
        assertNotNull("session " + index + " should carry the tracking attribute",
                this.sessions.get(index).getAttribute(Attributes.UNAUTHENTICATED_SESSION.getValue()));
    }

    private void thenSessionIsNotMarkedAsUnauthenticated(final int index) {
        assertNull("session " + index + " should not carry the tracking attribute",
                this.sessions.get(index).getAttribute(Attributes.UNAUTHENTICATED_SESSION.getValue()));
    }

    private void thenSlotReservationSucceeds() {
        assertNotNull(this.trackResult);
        assertTrue("the slot should have been reserved", this.trackResult);
    }

    private void thenSlotReservationFails() {
        assertNotNull(this.trackResult);
        assertFalse("the slot reservation should have failed", this.trackResult);
    }

    private void thenSessionIsReportedAsTrackedOrAuthenticated(final int index) {
        assertTrue("session " + index + " should be reported as tracked or authenticated",
                this.tracker.isTrackedOrAuthenticated(this.sessions.get(index)));
    }

    private void thenSessionIsNotReportedAsTrackedOrAuthenticated(final int index) {
        assertFalse("session " + index + " should not be reported as tracked or authenticated",
                this.tracker.isTrackedOrAuthenticated(this.sessions.get(index)));
    }

    /**
     * Mirrors the compound reserve-then-attach pattern used by production callers (see
     * {@code Console.getOrCreateSessionInternal}): checks whether the session is already tracked or authenticated
     * before reserving a new slot, and releases the slot again if attaching turns out to be unnecessary.
     */
    private boolean trackSession(final int index, final int maxCount) {
        final HttpSession session = this.sessions.get(index);

        if (this.tracker.isTrackedOrAuthenticated(session)) {
            return true;
        }

        try (final TrackingToken token = this.tracker.reserveToken(maxCount)) {
            if (!this.tracker.isTrackedOrAuthenticated(session)) {
                token.attach(session);
            }
            return true;
        } catch (final KuraException e) {
            return false;
        }
    }
